package cloud.gitwide.ampverse;
import android.app.*;
import android.widget.*;
import org.json.*;
import java.util.concurrent.*;
import java.util.function.Supplier;

/** Shared Full/standalone saved-library flow. Network/storage work never runs on the UI thread. */
final class CastLibraryView extends LinearLayout {
    private final Activity a;private final Appearance colors;private final CastPanel.Listener listener;private final Supplier<CastClient> selected;private final java.util.function.Consumer<String> download;
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final TextView status;private final Spinner output;private final LinearLayout rows,lists;private final EditText query;
    private volatile CastClient client;private volatile JSONObject identity;private JSONArray catalog=new JSONArray();private int offset,total;private boolean busy,supported;private volatile boolean closed;private volatile long epoch;
    CastLibraryView(Activity a,Appearance colors,CastPanel.Listener listener,Supplier<CastClient> selected,java.util.function.Consumer<String> download){
        super(a);this.a=a;this.colors=colors;this.listener=listener;this.selected=selected;this.download=download;setOrientation(VERTICAL);setVisibility(GONE);
        addView(label("Server Library",20));status=label("",14);addView(status);
        output=new Spinner(a);output.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"This phone · AMP Player","Selected server · speakers"}));addView(output);
        LinearLayout actions=new LinearLayout(a);actions.addView(button("Stop",this::stop),new LayoutParams(0,-2,1));actions.addView(button("Remote",()->{CastClient c=client;if(current(c))a.startActivity(new android.content.Intent(android.content.Intent.ACTION_VIEW,android.net.Uri.parse(c.base+"/")));}),new LayoutParams(0,-2,1));addView(actions);
        addView(button("Enable saved-playlist sync",this::enable));
        query=new EditText(a);query.setHint("Search selected server library");query.setSingleLine(true);query.setTextColor(colors.text);addView(query);
        addView(button("Search",()->load(0)));
        rows=new LinearLayout(a);rows.setOrientation(VERTICAL);addView(rows);
        LinearLayout pages=new LinearLayout(a);pages.addView(button("Previous",()->load(Math.max(0,offset-50))),new LayoutParams(0,-2,1));pages.addView(button("Next",()->{if(offset+50<total)load(offset+50);}),new LayoutParams(0,-2,1));addView(pages);
        addView(button("Refresh saved playlists",this::loadLists));
        LinearLayout create=new LinearLayout(a);create.addView(button("New playlist",()->create(false)),new LayoutParams(0,-2,1));create.addView(button("New Smart",()->create(true)),new LayoutParams(0,-2,1));addView(create);
        lists=new LinearLayout(a);lists.setOrientation(VERTICAL);addView(lists);
    }
    private TextView label(String text,int size){TextView v=new TextView(a);v.setText(text);v.setTextSize(size);v.setTextColor(colors.text);v.setPadding(0,8,0,8);return v;}
    private Button button(String text,Runnable action){Button b=new Button(a);b.setText(text);b.setAllCaps(false);b.setTextColor(Chrome.ink(colors,false));b.setBackground(Chrome.button(colors,false));b.setMinHeight((int)(48*getResources().getDisplayMetrics().density));b.setOnClickListener(v->action.run());return b;}
    private boolean current(CastClient c){return !closed&&c!=null&&client==c&&selected.get()==c;}
    void bind(CastClient c,JSONObject status){epoch++;client=c;identity=status;supported=CastLibraryModel.supports(status);setVisibility(VISIBLE);rows.removeAllViews();lists.removeAllViews();query.setText("");this.status.setText(supported?"Tap a song to play on the selected output. Downloads are separate.":"Update this server for library Player support. Browsing does not change playback.");load(0);}
    private interface Task {String run(CastClient c,long version)throws Exception;}
    private void work(Task task){CastClient c=client;long version=epoch;if(!current(c)||busy)return;busy=true;status.setText("Loading selected server…");worker.execute(()->{String message;try{if(!current(c)||version!=epoch)throw new IllegalStateException("Selected server changed");message=task.run(c,version);}catch(Exception e){message=e.getMessage()==null?"Server request failed":e.getMessage();}String result=message;a.runOnUiThread(()->{busy=false;if(current(c)&&version==epoch)status.setText(result);else if(!closed&&current(client))load(0);});});}
    private void ui(CastClient c,long version,Runnable action){a.runOnUiThread(()->{if(current(c)&&version==epoch)action.run();});}
    private JSONObject authority()throws JSONException{return new JSONObject().put("server_id",identity.getString("server_id")).put("library_id",identity.getString("library_id"));}
    private void load(int page){String search=query.getText().toString();work((c,v)->{JSONObject data=c.get("/api/studio/tracks?offset="+page+"&limit=50&q="+android.net.Uri.encode(search));JSONArray tracks=data.getJSONArray("tracks");if(tracks.length()>50)throw new JSONException("Unexpected server page");for(int i=0;i<tracks.length();i++)CastLibraryModel.path(tracks.getJSONObject(i).getString("path"));ui(c,v,()->{offset=page;total=data.optInt("total");catalog=tracks;rows.removeAllViews();for(int i=0;i<tracks.length();i++){JSONObject t=tracks.optJSONObject(i);rows.addView(button(t.optString("title",t.optString("path")),()->playPaths(new JSONArray().put(t.optString("path")))));}});return "Songs "+(page+1)+"–"+(page+tracks.length())+" of "+data.optInt("total")+" · "+identity.optString("station_name","selected server");});}
    private void playPaths(JSONArray paths){if(!supported){status.setText("Update server for stable library Player support");return;}final boolean speakers=output.getSelectedItemPosition()==1;if(!speakers&&!listener.phoneAvailable()){status.setText("Open the matching AMP Player before phone listening");return;}final String library=identity.optString("library_id");work((c,v)->{c.status();if(!current(c)||v!=epoch)throw new IllegalStateException("Selected server changed");c.post("/api/player/play",CastLibraryModel.play(library,paths,speakers));if(!speakers)ui(c,v,()->listener.listen(c.phoneStream(),"Server Library"));return speakers?"Server speaker playback requested; verify its audio device.":"Streaming through AMP Player on this phone. No offline copy was created.";});}
    private void stop(){if(output.getSelectedItemPosition()==0){listener.stopListening();status.setText("Phone listening stopped; server program unchanged");}else work((c,v)->{c.status();if(!current(c)||v!=epoch)throw new IllegalStateException("Selected server changed");c.command(false);return "Selected server program stopped";});}
    private void enable(){CastClient c=client;if(!current(c))return;new AlertDialog.Builder(a).setTitle("Enable saved-playlist sync?").setMessage("Use this selected server/library for saved edits? AMP Player retains drafts and encrypts its private access code. Sync pulls do not replace playback or open editors.").setPositiveButton("Enable",(d,n)->work((owner,v)->{final JSONObject args=authority();owner.withPrivateAuthorization((base,password,server,library)->{try{args.put("base",base).put("password",password);}catch(JSONException e){throw new IllegalStateException(e);}});return ModuleRpc.call(a,"playlist_sync_enable",args).optString("message");})).setNegativeButton("Cancel",null).show();}
    private void loadLists(){work((c,v)->{JSONObject snapshot=c.get("/api/sync/v1/playlists");if(!identity.getString("server_id").equals(snapshot.getString("server_id"))||!identity.getString("library_id").equals(snapshot.getString("library_id")))throw new JSONException("Server/library changed");JSONArray docs=snapshot.getJSONArray("documents");if(docs.length()>1000)throw new JSONException("Too many playlists");ui(c,v,()->{lists.removeAllViews();for(int i=0;i<docs.length();i++){JSONObject e=docs.optJSONObject(i);lists.addView(button(e.optJSONObject("document").optString("name")+" · "+e.optString("kind"),()->open(e)));}});return docs.length()+" saved server playlists · edits require enabled sync";});}
    private void create(boolean smart){EditText name=new EditText(a);name.setHint("Saved server playlist name");new AlertDialog.Builder(a).setTitle(smart?"New Smart Playlist":"New server playlist").setView(name).setPositiveButton("Create",(d,n)->{String value=name.getText().toString().trim();work((c,v)->ModuleRpc.call(a,"playlist_sync_create",authority().put("smart",smart).put("name",value)).optString("message"));}).setNegativeButton("Cancel",null).show();}
    private void open(JSONObject envelope){try{
        JSONObject captured=new JSONObject(envelope.toString()),draft=new JSONObject(captured.getJSONObject("document").toString());boolean smart=captured.getString("kind").equals("smart");LinearLayout form=new LinearLayout(a);form.setOrientation(VERTICAL);EditText name=new EditText(a);name.setText(draft.optString("name"));form.addView(name);
        form.addView(label("Saved edits retain the captured revision and full unknown rules. Current playback and unsaved drafts stay unchanged.",14));
        Button play=button("Play",()->{if(!smart){JSONArray refs=captured.optJSONObject("document").optJSONArray("tracks"),paths=new JSONArray();for(int i=0;refs!=null&&i<refs.length();i++)paths.put(refs.optJSONObject(i).optString("relative_path"));playPaths(paths);}else playSmart(captured);});form.addView(play);form.addView(button("Download offline + cues",()->download.accept(captured.optString("document_id"))));
        Spinner style=new Spinner(a);style.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"steady","hype","chill"}));style.setSelection(Math.max(0,java.util.Arrays.asList("steady","hype","chill").indexOf(draft.optString("style","steady"))));EditText energy=new EditText(a);energy.setHint("Target energy 1–10; blank = Auto");energy.setInputType(8194);energy.setText(draft.isNull("target_energy")?"":draft.optString("target_energy"));
        if(smart){form.addView(style);form.addView(energy);form.addView(label("Other Smart filters remain saved unchanged. Full filter editing is available in Remote.",14));}
        else{form.addView(button("Add server song",()->add(draft)));form.addView(button("Order / remove references",()->order(draft)));}
        ScrollView scroll=new ScrollView(a);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Saved server playlist").setView(scroll).setPositiveButton("Save",null).setNegativeButton("Close",null).create();
        final CastClient owner=client;final long version=epoch;dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(z->{try{if(!current(owner)||version!=epoch)throw new IllegalStateException("Server changed; reopen this playlist");JSONObject edited=CastLibraryModel.edited(new JSONObject(captured.toString()).put("document",draft),name.getText().toString(),style.getSelectedItem().toString(),energy.getText().toString());JSONObject args=authority().put("envelope",captured).put("document",edited);work((c,v)->ModuleRpc.call(a,"playlist_sync_save",args).optString("message"));dialog.dismiss();}catch(Exception e){status.setText(e.getMessage());}}));dialog.show();
    }catch(Exception e){status.setText(e.getMessage());}}
    private void playSmart(JSONObject envelope){if(!supported){status.setText("Update server for Player playlist support");return;}boolean speakers=output.getSelectedItemPosition()==1;if(!speakers&&!listener.phoneAvailable()){status.setText("Open AMP Player for phone listening");return;}work((c,v)->{c.status();if(!current(c)||v!=epoch)throw new IllegalStateException("Selected server changed");c.post("/api/player/play",new JSONObject().put("library_id",identity.getString("library_id")).put("playlist_id",envelope.getString("document_id")).put("shuffle",false).put("server_speakers",speakers));if(!speakers)ui(c,v,()->listener.listen(c.phoneStream(),envelope.getJSONObject("document").optString("name")));return "Saved Smart Playlist requested on selected output";});}
    private void add(JSONObject draft){String[] names=new String[catalog.length()];for(int i=0;i<names.length;i++)names[i]=catalog.optJSONObject(i).optString("title",catalog.optJSONObject(i).optString("path"));final JSONArray captured=catalog;new AlertDialog.Builder(a).setTitle("Add from current library page · duplicates allowed").setItems(names,(d,n)->{try{String path=CastLibraryModel.path(captured.getJSONObject(n).getString("path"));draft.getJSONArray("tracks").put(new JSONObject().put("library_id",identity.getString("library_id")).put("relative_path",path).put("track_key",trackKey(path)));}catch(Exception e){status.setText(e.getMessage());}}).setNegativeButton("Close",null).show();}
    private static String trackKey(String path)throws Exception {byte[] hash=java.security.MessageDigest.getInstance("SHA-256").digest(path.getBytes(java.nio.charset.StandardCharsets.UTF_8));return String.format(java.util.Locale.ROOT,"song_%064x",new java.math.BigInteger(1,hash));}
    private void order(JSONObject draft){try{JSONArray refs=draft.getJSONArray("tracks");String[] names=new String[refs.length()];for(int i=0;i<names.length;i++)names[i]=(i+1)+". "+refs.getJSONObject(i).getString("relative_path");new AlertDialog.Builder(a).setTitle("Saved order · missing references retained").setItems(names,(d,n)->new AlertDialog.Builder(a).setItems(new String[]{"Move up","Move down","Remove"},(x,op)->{try{java.util.List<JSONObject> all=new java.util.ArrayList<>();for(int i=0;i<refs.length();i++)all.add(refs.getJSONObject(i));if(op==0&&n>0)java.util.Collections.swap(all,n,n-1);if(op==1&&n+1<all.size())java.util.Collections.swap(all,n,n+1);if(op==2)all.remove(n);draft.put("tracks",new JSONArray(all));order(draft);}catch(Exception e){status.setText(e.getMessage());}}).show()).setNegativeButton("Done",null).show();}catch(Exception e){status.setText(e.getMessage());}}
    void close(){closed=true;epoch++;worker.shutdownNow();}
}
